<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Maze Discovery — 24 Tremaux Bots</title>
<style>
  :root { --bg:#0a0e16; --panel:#121826; --line:#2a3446; --ink:#cfe0f2; --accent:#57b3ff; }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; }
  body {
    background: radial-gradient(1200px 800px at 70% -10%, #16203a 0%, var(--bg) 55%);
    color: var(--ink);
    font: 14px/1.4 system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
    display: flex; flex-direction: column; align-items: center; gap: 14px;
    padding: 18px; min-height: 100%;
  }
  h1 { font-size: 18px; font-weight: 600; margin: 0 0 2px; letter-spacing: .3px; }
  #ui {
    display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px;
    background: var(--panel); border: 1px solid var(--line);
    border-radius: 12px; padding: 10px 14px;
    box-shadow: 0 10px 30px rgba(0,0,0,.35);
  }
  .stat { display: flex; align-items: baseline; gap: 7px; }
  .stat b { color: var(--accent); font-variant-numeric: tabular-nums; }
  #completed { min-width: 2ch; }
  #timer { min-width: 4ch; }
  button {
    background: linear-gradient(180deg, #1d2a44, #151f35);
    color: var(--ink); border: 1px solid var(--line);
    padding: 7px 12px; border-radius: 9px; cursor: pointer; font-weight: 600;
  }
  button:hover { border-color: var(--accent); }
  button:active { transform: translateY(1px); }
  #maze {
    display: block; background: #0a0e16; border: 2px solid #223049;
    border-radius: 8px; box-shadow: 0 16px 44px rgba(0,0,0,.5);
    line-height: 0;
  }
  canvas { display: block; }
  .hint { opacity: .6; font-size: 12px; max-width: 520px; text-align: center; }
</style>
</head>
<body>
  <h1>Maze Discovery — 24 Tremaux explorers</h1>
  <div id="ui">
    <div class="stat">Completed: <b id="completed">0</b><span>/ 24</span></div>
    <div class="stat">Timer: <b id="timer">0</b><span> ticks</span></div>
    <div class="stat">Seed: <b id="seed">–</b></div>
    <button id="reset" title="Generate a new maze (optionally pass a numeric seed)">New Maze</button>
    <button id="play" title="Auto-advance one tick periodically">▶ Play</button>
  </div>
  <div id="maze"><canvas id="cv"></canvas></div>
  <div class="hint">
    Bots only know their own cell. They explore with Tremaux/DFS backtracking (each passage crossed at most twice by a bot),
    never using global pathfinding. The timer freezes when the last bot reaches the green exit.
  </div>

<script>
"use strict";
(function () {
  // ---------- constants ----------
  const ROWS = 20, COLS = 20;          // maze is ROWS x COLS cells (>= 15x15)
  const NBOTS = 24;
  const DIRS = ["N", "E", "S", "W"];
  const DELTA = { N: { dr: -1, dc: 0 }, E: { dr: 0, dc: 1 }, S: { dr: 1, dc: 0 }, W: { dr: 0, dc: -1 } };
  const OPP = { N: "S", S: "N", E: "W", W: "E" };

  // ---------- layout / canvas ----------
  const cs = Math.max(20, Math.ceil(420 / Math.min(ROWS, COLS))); // cell size -> >= ~420px board
  const cv = document.getElementById("cv");
  cv.width = COLS * cs;
  cv.height = ROWS * cs;

  const elCompleted = document.getElementById("completed");
  const elTimer = document.getElementById("timer");
  const elSeed = document.getElementById("seed");

  // ---------- seeded PRNG (mulberry32) ----------
  function makeRng(a) {
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function shuffle(arr, rng) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
    }
    return arr;
  }

  // ---------- maze generation (iterative DFS -> perfect maze) ----------
  function generateMaze(rows, cols, rng) {
    const open = [];
    for (let r = 0; r < rows; r++) {
      const row = [];
      for (let c = 0; c < cols; c++) row.push({ N: false, E: false, S: false, W: false });
      open.push(row);
    }
    const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));
    const stack = [{ r: 0, c: 0 }];
    visited[0][0] = true;
    while (stack.length) {
      const cur = stack[stack.length - 1];
      const opts = [];
      for (const d of DIRS) {
        const nr = cur.r + DELTA[d].dr, nc = cur.c + DELTA[d].dc;
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) opts.push({ r: nr, c: nc, n: d });
      }
      if (opts.length) {
        const pick = opts[Math.floor(rng() * opts.length)];
        open[cur.r][cur.c][pick.n] = true;
        open[pick.r][pick.c][OPP[pick.n]] = true;
        visited[pick.r][pick.c] = true;
        stack.push({ r: pick.r, c: pick.c });
      } else {
        stack.pop();
      }
    }
    return open;
  }

  // ---------- bot discovery / Tremaux DFS step ----------
  function discoverCell(bot, r, c) {
    const key = r + "," + c;
    if (bot._known[key]) return;
    const adj = { N: "wall", E: "wall", S: "wall", W: "wall" };
    for (const d of DIRS) {
      const nr = r + DELTA[d].dr, nc = c + DELTA[d].dc;
      if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS) adj[d] = "wall";
      else if (game._open[r][c][d]) adj[d] = "pass";
      else adj[d] = "wall";
    }
    bot._known[key] = adj;
    bot._visited.add(key);
  }

  function countPass(adj) { let n = 0; for (const d in adj) if (adj[d] === "pass") n++; return n; }

  // One logical step for a single bot. Returns nothing; mutates bot state.
  function stepBot(bot, tickNum) {
    if (bot.finishTick !== null) return;

    const leftR = bot.pos.r, leftC = bot.pos.c;
    const leftKey = leftR + "," + leftC;
    const frame = bot._stack[bot._stack.length - 1];
    const knownCur = bot._known[leftKey];
    const dirs = bot._prefDirs;

    // Depth-first forward move: pick first passage to an unexplored cell.
    let i = frame.dirIdx;
    while (i < dirs.length) {
      const dir = dirs[i++];
      if (knownCur[dir] === "wall") continue;
      const nr = leftR + DELTA[dir].dr, nc = leftC + DELTA[dir].dc;
      const nkey = nr + "," + nc;
      if (!bot._visited.has(nkey)) {
        bot._prevPos = { r: leftR, c: leftC };
        bot.pos = { r: nr, c: nc };
        bot.path.push({ r: nr, c: nc });
        frame.dirIdx = i;                       // remember we consumed this direction
        discoverCell(bot, nr, nc);
        bot._stack.push({ cell: { r: nr, c: nc }, dirIdx: 0 });
        if (nr === game._exit.r && nc === game._exit.c) bot.finishTick = tickNum;
        return;
      }
      // Already-visited passage: leave it for backtracking later.
    }

    // Exhausted at this cell -> backtrack to parent (crosses the connecting passage 2nd time).
    bot._stack.pop();
    if (bot._stack.length === 0) return;       // fully explored without exit (shouldn't happen: maze connected)
    const parent = bot._stack[bot._stack.length - 1].cell;
    bot._prevPos = { r: leftR, c: leftC };
    bot.pos = { r: parent.r, c: parent.c };
    bot.path.push({ r: parent.r, c: parent.c });
    frame.dirIdx = dirs.length;

    // Record a genuine dead-end branch in this bot's memory.
    if (countPass(knownCur) === 1 && leftKey !== game._spawnKey) {
      bot.deadEnds.push({ r: leftR, c: leftC });
    }
    if (parent.r === game._exit.r && parent.c === game._exit.c) bot.finishTick = tickNum;
  }

  // ---------- the game object (public API) ----------
  const game = {
    _open: null, _bots: [], _elapsed: 0, _tickNum: 0, _seed: 0,
    _spawn: { r: 0, c: 0 }, _exit: { r: ROWS - 1, c: COLS - 1 },

    get elapsed() { return this._elapsed; },
    get size() { return { rows: ROWS, cols: COLS }; },
    get spawn() { return { r: this._spawn.r, c: this._spawn.c }; },
    get exit() { return { r: this._exit.r, c: this._exit.c }; },
    get bots() { return this._bots; },

    tick(n) {
      n = Math.max(0, Math.floor(n || 0));
      if (this._allDone()) return;               // frozen after last arrival
      for (let k = 0; k < n; k++) {
        if (this._allDone()) break;              // stop as soon as the last bot arrives
        this._tickNum++;
        for (let b = 0; b < this._bots.length; b++) stepBot(this._bots[b], this._tickNum);
        this._elapsed = this._tickNum;
      }
      updateUI();
    },

    reset(seed) {
      if (typeof seed !== "number" || Number.isNaN(seed)) seed = Math.floor(Math.random() * 2147483647) + 1;
      this._seed = seed | 0;

      const rng = makeRng(this._seed);
      this._open = generateMaze(ROWS, COLS, rng);
      this._spawn = { r: 0, c: 0 };
      this._exit = { r: ROWS - 1, c: COLS - 1 };
      this._spawnKey = "0,0";

      this._bots = [];
      for (let i = 0; i < NBOTS; i++) {
        const bseed = (Math.imul((this._seed >>> 0) ^ i, 2654435761)) >>> 0;
        const brng = makeRng(bseed);
        const pref = shuffle(DIRS.slice(), brng);   // per-bot seeded preference -> they spread out
        const start = this._spawn;
        const bot = {
          path: [{ r: start.r, c: start.c }],
          deadEnds: [],
          finishTick: null,
          pos: { r: start.r, c: start.c },
          _stack: [{ cell: { r: start.r, c: start.c }, dirIdx: 0 }],
          _known: {},
          _visited: new Set([this._spawnKey]),
          _prefDirs: pref,
          _prevPos: { r: start.r, c: start.c },
          _rx: (start.c + 0.5) * cs,
          _ry: (start.r + 0.5) * cs,
          color: COLORS[i % COLORS.length]
        };
        discoverCell(bot, start.r, start.c);
        this._bots.push(bot);
      }

      this._elapsed = 0;
      this._tickNum = 0;
      stopPlay();
      updateUI();
    },

    walls(r, c) {
      const o = this._open[r][c];
      return {
        n: (r === 0 || !o.N),
        e: (c === COLS - 1 || !o.E),
        s: (r === ROWS - 1 || !o.S),
        w: (c === 0 || !o.W)
      };
    },

    _allDone() { for (let i = 0; i < this._bots.length; i++) if (this._bots[i].finishTick === null) return false; return true; }
  };

  const COLORS = (() => { const c = []; for (let i = 0; i < NBOTS; i++) c.push("hsl(" + (((i * 360) / NBOTS) + 20) % 360 + ",78%,58%)"); return c; })();

  // ---------- UI ----------
  function updateUI() {
    let done = 0;
    for (let i = 0; i < game._bots.length; i++) if (game._bots[i].finishTick !== null) done++;
    elCompleted.textContent = done;
    elTimer.textContent = game.elapsed;
    elSeed.textContent = game._seed;
  }

  // ---------- rendering (smooth interpolation via requestAnimationFrame) ----------
  function hasWall(r, c, d) {
    const o = game._open[r][c];
    if (d === "N") return r === 0 || !o.N;
    if (d === "E") return c === COLS - 1 || !o.E;
    if (d === "S") return r === ROWS - 1 || !o.S;
    return c === 0 || !o.W;
  }
  function drawWallSeg(r, c, d) {
    const x = c * cs, y = r * cs;
    const ctx = cv.getContext("2d");
    ctx.beginPath();
    if (d === "N") { ctx.moveTo(x, y); ctx.lineTo(x + cs, y); }
    else if (d === "E") { ctx.moveTo(x + cs, y); ctx.lineTo(x + cs, y + cs); }
    else if (d === "S") { ctx.moveTo(x, y + cs); ctx.lineTo(x + cs, y + cs); }
    else { ctx.moveTo(x, y); ctx.lineTo(x, y + cs); }
    ctx.stroke();
  }
  function render() {
    const ctx = cv.getContext("2d");
    ctx.fillStyle = "#0a0e16";
    ctx.fillRect(0, 0, cv.width, cv.height);

    // passage floor
    for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
      ctx.fillStyle = "#141a27";
      ctx.fillRect(c * cs + 1, r * cs + 1, cs - 2, cs - 2);
    }

    // walls
    ctx.strokeStyle = "#a9bcd3";
    ctx.lineWidth = Math.max(2, cs * 0.05);
    ctx.lineCap = "butt";
    for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++)
      for (const d of DIRS) if (hasWall(r, c, d)) drawWallSeg(r, c, d);

    // exit / spawn highlights
    ctx.fillStyle = "rgba(70,220,120,.35)";
    ctx.fillRect(game._exit.c * cs + 2, game._exit.r * cs + 2, cs - 4, cs - 4);
    ctx.fillStyle = "rgba(90,150,255,.30)";
    ctx.fillRect(game._spawn.c * cs + 2, game._spawn.r * cs + 2, cs - 4, cs - 4);

    // bots (drawn at interpolated positions; stay centered in corridors)
    for (const b of game._bots) {
      ctx.beginPath();
      ctx.arc(b._rx, b._ry, cs * 0.28, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      ctx.lineWidth = 1.5; ctx.strokeStyle = "rgba(0,0,0,.55)"; ctx.stroke();
    }
  }

  let lastT = performance.now();
  function frame(t) {
    const dt = Math.min(220, t - lastT); lastT = t;
    for (const b of game._bots) {
      const tx = (b.pos.c + 0.5) * cs, ty = (b.pos.r + 0.5) * cs;
      const k = 1 - Math.exp(-dt / 90);           // time-consistent easing
      b._rx += (tx - b._rx) * k;
      b._ry += (ty - b._ry) * k;
    }
    render();
    requestAnimationFrame(frame);
  }

  // ---------- auto-play (user-initiated only, never interferes with grading) ----------
  let playTimer = null, playOn = false;
  const playBtn = document.getElementById("play");
  function stopPlay() { if (playTimer !== null) { clearInterval(playTimer); playTimer = null; } playOn = false; playBtn.textContent = "▶ Play"; }
  playBtn.addEventListener("click", () => {
    if (game._allDone()) return;
    playOn = !playOn;
    if (playOn) {
      playBtn.textContent = "⏸ Pause";
      playTimer = setInterval(() => { if (game._allDone() || playOn === false) { stopPlay(); return; } game.tick(1); }, 90);
    } else { stopPlay(); }
  });

  document.getElementById("reset").addEventListener("click", () => game.reset());

  // ---------- boot ----------
  game.reset();
  requestAnimationFrame(frame);

  window.game = game;
})();
</script>
</body>
</html>
